        self.value = value
        self.left = left
        self.right = right

#        8
#      /   \
#     3     10
#    / \      \
#   1   6      14
root = Node(8, Node(3, Node(1), Node(6)), Node(10, None, Node(14)))

def in_order(node):
    if node is None:
        return []
    return in_order(node.left) + [node.value] + in_order(node.right)

print(in_order(root))   # [1, 3, 6, 8, 10, 14] — sorted!

